import { escapeHtml as e, money, dateLabel, priceLabel, reviewStats, reviewSources, sortReviews, quickFacts, weddingMatches, recommendedPackage, availabilityOn, monthCells } from './model.js';

const paths = {
  heart: '<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
  share: '<path d="M12 16V3m-4 4 4-4 4 4M5 12v8h14v-8"/>',
  pin: '<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',
  star: '<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/>',
  arrow: '<path d="M4 12h16m-6-6 6 6-6 6"/>',
  chevron: '<path d="m9 5 7 7-7 7"/>',
  check: '<path d="m5 12 4 4L19 6"/>',
  close: '<path d="m6 6 12 12M6 18 18 6"/>',
  calendar: '<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',
  flower: '<path d="M12 8c-5-9-11 0-5 3-8 2-2 11 3 6-1 9 10 7 7 0 8 4 12-6 4-8 5-6-5-12-9-1Z" transform="translate(-1 -1) scale(.9)"/><circle cx="12" cy="12" r="2"/>',
  leaf: '<path d="M20 3C8 1 1 8 6 15s15 2 14-12ZM5 20l11-12"/>',
  spark: '<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z"/>',
  truck: '<path d="M2 6h12v11H2Zm12 4h4l4 4v3h-8"/><circle cx="6" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',
  wallet: '<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 8h18m-5 4h5v5h-5z"/>',
  people: '<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-16a3 3 0 0 1 0 6m2 4a6 6 0 0 1 3 5"/>',
  grid: '<rect x="3" y="3" width="6" height="6" rx="1"/><rect x="15" y="3" width="6" height="6" rx="1"/><rect x="3" y="15" width="6" height="6" rx="1"/><rect x="15" y="15" width="6" height="6" rx="1"/>',
  play: '<path d="m9 5 11 7-11 7Z"/>',
  compare: '<path d="M8 3v18M16 3v18M3 7h10m-2-3 3 3-3 3m10 7H11m2-3-3 3 3 3"/>',
  message: '<path d="M21 4H3v13h4v4l5-4h9ZM7 8h10M7 12h6"/>',
  plus: '<path d="M12 4v16M4 12h16"/>',
  clock: '<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
  info: '<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>'
};
export const icon = (name, cls = '') => `<svg class="vp-icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.spark}</svg>`;
export const button = (text, action, cls = 'vp-button', attrs = '') => `<button type="button" class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const image = (photo, { eager = false, cls = '' } = {}) => `<img src="${e(photo.src)}" alt="${e(photo.alt)}" class="${cls}" style="object-position:${e(photo.position || 'center')}" ${eager ? 'fetchpriority="high" loading="eager"' : 'loading="lazy"'} decoding="async" width="1400" height="1000">`;
const title = (eyebrow, heading, extra = '') => `<div class="vp-section-heading"><div><p class="vp-eyebrow">${e(eyebrow)}</p><h2>${e(heading)}</h2></div>${extra}</div>`;
const list = values => `<ul class="vp-checklist">${values.map(value => `<li>${icon('check')}<span>${e(value)}</span></li>`).join('')}</ul>`;
export function renderMatch(vendor, couple) {
  if (!couple?.isLoggedIn) return `<div class="vp-match-intro">${icon('spark')}<div><p class="vp-eyebrow">A LITTLE MORE PERSONAL</p><h2>Is this your kind of wedding vendor?</h2><p>Add your wedding details to see how location, style and starting prices line up.</p>${button('Explore with sample wedding details ' + icon('arrow'), 'sign-in', 'vp-text-button')}</div></div>`;
  const matches = weddingMatches(vendor, couple);
  return `<div class="vp-match-heading"><div><p class="vp-eyebrow">YOUR WEDDING, CONSIDERED</p><h2>A little more you.</h2><p>How this vendor matches your wedding${couple.wedding?.city ? ` in ${e(couple.wedding.city)}` : ''}.</p></div><span class="vp-match-monogram">${icon('spark')}</span></div>${matches.length ? `<div class="vp-match-grid">${matches.map(match => `<div class="vp-match-item"><span class="vp-match-symbol vp-state-${match.state}">${icon(match.state === 'match' ? 'check' : match.icon)}</span><div><strong>${e(match.title)}</strong><p>${e(match.detail)}</p><span class="vp-state-label">${({ match: 'Match', potential: 'Potential match', unknown: 'Unknown', no: 'Does not match' })[match.state]}</span></div></div>`).join('')}</div>` : '<p>Add a date, location or budget in the preview controls to see supported matches.</p>'}<p class="vp-fine">Based on the sample wedding details. A starting price is not a final quote, and no date is reserved.</p>`;
}
export function renderPackage(pkg, vendor, recommended) {
  return `<article class="vp-package${recommended ? ' vp-package-recommended' : ''}" id="package-${e(pkg.id)}">${pkg.image ? `<div class="vp-package-image">${image(pkg.image)}${recommended ? '<span>A starting point for your budget</span>' : ''}</div>` : ''}<div class="vp-package-copy"><p class="vp-eyebrow">${e(pkg.subtitle || 'TAILORED TO YOUR DAY')}</p><h3>${e(pkg.name)}</h3><p class="vp-package-price">${e(priceLabel(pkg, vendor.pricing.currency))}</p><p>${e(pkg.description)}</p><details data-package="${e(pkg.id)}"><summary>Inclusions & details ${icon('plus')}</summary><div class="vp-package-details"><h4>What’s included</h4>${list(pkg.inclusions || [])}${pkg.extras?.length ? `<h4>Quoted separately</h4>${list(pkg.extras)}` : ''}${pkg.conditions ? `<p class="vp-fine">${e(pkg.conditions)}</p>` : ''}</div></details><div class="vp-package-actions">${button('Request a quote ' + icon('arrow'), 'enquire', 'vp-button', `data-type="package" data-package="${e(pkg.id)}"`)}${pkg.budgetEligible !== false ? button(icon('plus') + ' Add to wedding budget', 'budget', 'vp-text-button', `data-package="${e(pkg.id)}"`) : ''}</div></div></article>`;
}
export function renderAvailability(vendor, selectedDate, month) {
  const mode = vendor.availability.mode;
  let content = '';
  if (mode === 'live') {
    const monthTitle = new Intl.DateTimeFormat('en-AU', { month: 'long', year: 'numeric' }).format(new Date(month + '-01T12:00:00'));
    content = `<div class="vp-calendar"><div class="vp-calendar-heading">${button(icon('chevron'), 'month', 'vp-icon-button vp-prev', 'data-shift="-1" aria-label="Previous month"')}<h3 aria-live="polite">${monthTitle}</h3>${button(icon('chevron'), 'month', 'vp-icon-button', 'data-shift="1" aria-label="Next month"')}</div><div class="vp-calendar-grid" role="group" aria-label="${e(monthTitle)} availability">${['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(day => `<span class="vp-day-label">${day}</span>`).join('')}${monthCells(month).map(date => date ? `<button type="button" data-action="select-date" data-date="${date}" class="vp-day vp-day-${availabilityOn(vendor, date)}${date === selectedDate ? ' is-selected' : ''}" aria-label="${e(dateLabel(date))}, ${availabilityOn(vendor, date)}" aria-pressed="${date === selectedDate}">${Number(date.slice(-2))}</button>` : '<span></span>').join('')}</div><div class="vp-calendar-key"><span class="vp-dot-available">Available</span><span class="vp-dot-unavailable">Unavailable</span><span class="vp-dot-blackout">Blackout</span><span class="vp-dot-unknown">Unknown</span></div><p class="vp-fine">Illustrative calendar. Unknown dates are not confirmed available.</p></div>`;
  }
  const status = availabilityOn(vendor, selectedDate);
  return `<div class="vp-availability-layout">${content}<div><p class="vp-subhead">${mode === 'live' ? 'Make a little room for your date.' : mode === 'request' ? 'Let’s start with your date.' : 'Planning your day? Start a conversation.'}</p><p>${mode === 'live' ? 'Choose a day to see the sample calendar status, then enquire about the details.' : mode === 'request' ? 'Availability changes as plans come together. Share your wedding date and we can show how an availability enquiry would work.' : 'This vendor does not publish a calendar. Include your date in a general enquiry to discuss the possibilities.'}</p><label class="vp-field"><span>Your wedding date${mode === 'unpublished' ? ' (optional)' : ''}</span><input type="date" data-availability-date value="${e(selectedDate)}"></label>${mode === 'live' ? `<p class="vp-date-status" role="status">${dateLabel(selectedDate)}: <strong>${e(status)}</strong></p>` : ''}${button((mode === 'unpublished' ? 'Enquire about your day' : 'Check availability') + icon('arrow'), 'enquire', 'vp-button', `data-type="${mode === 'unpublished' ? 'general' : 'availability'}"`)}<p class="vp-fine">An enquiry is not a booking or a reservation.</p></div></div>`;
}
export function renderReviews(vendor, order = 'recent', count = 3) {
  if (!vendor.reviews.length) return '<div class="vp-empty"><p>No reviews published yet.</p><p>Explore the portfolio and ask the vendor about their experience.</p></div>';
  return `<div class="vp-review-grid">${sortReviews(vendor.reviews, order).slice(0, count).map(review => `<article class="vp-review"><div class="vp-review-person"><span>${e(review.name[0])}</span><div><strong>${e(review.name)}</strong><small>${e(review.weddingLocation || '')}</small></div><span class="vp-review-stars" aria-label="${review.rating} out of 5">${icon('star')} ${review.rating}.0</span></div><h3>${e(review.title)}</h3><p>${e(review.body.slice(0, 210))}${review.body.length > 210 ? '…' : ''}</p>${button('Read full review', 'review', 'vp-text-button', `data-review="${e(review.id)}"`)}<p class="vp-review-source">${e(reviewSources[review.source] || 'Sample review')}<br>${e(dateLabel(review.date))}</p>${review.photos?.length ? `<div class="vp-review-photos">${review.photos.map((photo, i) => button(image(photo), 'review-photo', 'vp-photo-button', `data-review="${e(review.id)}" data-index="${i}" aria-label="View review photograph ${i + 1}"`)).join('')}</div>` : ''}</article>`).join('')}</div>`;
}
export function renderProfile(vendor, couple, state = {}) {
  const stats = reviewStats(vendor.reviews), photos = vendor.media.gallery, facts = quickFacts(vendor), recommended = recommendedPackage(vendor, couple);
  const navItems = [['overview', 'Overview'], ['packages', 'Packages'], ['availability', 'Availability'], ...(vendor.portfolioGalleries.length || vendor.media.videos.length ? [['portfolio', 'Portfolio']] : []), ['location', 'Location'], ['reviews', 'Reviews'], ...(vendor.faqs.length ? [['faqs', 'FAQs']] : [])];
  const date = state.selectedDate || (couple.isLoggedIn ? couple.wedding?.date : '') || '', month = state.month || date.slice(0, 7) || '2027-10';
  return `<div class="vp-shell"><nav class="vp-breadcrumb" aria-label="Breadcrumb"><a href="../wedding-suppliers/">Wedding vendors</a>${icon('chevron')}<a href="../wedding-suppliers/${e(vendor.categorySlug || '')}/">${e(vendor.categoryLabel || vendor.category)}</a>${icon('chevron')}<span>${e(vendor.name)}</span></nav>
  <section class="vp-profile-heading" aria-labelledby="vp-name"><div><p class="vp-eyebrow">${e(vendor.categoryLabel || vendor.category)} <span>·</span> ${e(vendor.location.displayLocation)}</p><h1 id="vp-name">${e(vendor.name)}</h1><div class="vp-meta">${stats.count ? `<a href="#reviews" class="vp-rating">${icon('star')} <strong>${stats.average.toFixed(1)}</strong><span>(${stats.count} sample reviews)</span></a>` : '<span>No reviews yet</span>'}<span class="vp-meta-location">${icon('pin')}${e(vendor.location.displayLocation)}</span><span>${e(priceLabel(vendor.pricing, vendor.pricing.currency))}</span></div></div><div class="vp-heading-actions">${button(icon('share') + '<span>Share</span>', 'share', 'vp-quiet-button', 'aria-label="Share vendor profile"')}${button(icon('heart') + '<span data-save-label>Save</span>', 'save', 'vp-quiet-button', 'aria-pressed="false" data-save-button')}</div></section>
  <section class="vp-gallery-wrap" aria-label="${e(vendor.name)} photos"><div class="vp-gallery" data-gallery-strip data-count="${photos.length}">${photos.length ? photos.map((photo, index) => button(image(photo, { eager: index === 0 }), 'gallery', `vp-gallery-photo${index === 0 ? ' vp-gallery-main' : ''}`, `data-index="${index}" aria-label="Open photo ${index + 1} of ${photos.length}: ${e(photo.alt)}"`)).join('') : '<div class="vp-no-media">Photography coming soon</div>'}</div>${photos.length ? `<div class="vp-gallery-actions"><span class="vp-mobile-photo-count" data-mobile-photo-count>1 / ${photos.length}</span>${vendor.media.videos.length ? button(icon('play') + ' Studio film', 'video', 'vp-gallery-control', 'data-video="0"') : ''}${button(icon('grid') + ` All ${photos.length} photos`, 'gallery', 'vp-gallery-control', 'data-index="0"')}</div>` : ''}</section>
  <nav class="vp-section-nav" aria-label="On this profile">${navItems.map(([id, label], index) => `<a href="#${id}"${index === 0 ? ' class="is-active"' : ''}>${label}</a>`).join('')}</nav>
  <div class="vp-columns"><div class="vp-main-column"><section class="vp-match" id="wedding-match">${renderMatch(vendor, couple)}</section>
  <section class="vp-section vp-about" id="overview">${title('MEET YOUR PEOPLE', vendor.tagline || `A little about ${vendor.name}`)}<div class="vp-about-copy">${vendor.description.slice(0, 2).map(text => `<p>${e(text)}</p>`).join('')}${vendor.description.length > 2 ? `<details class="vp-read-more"><summary>More about the studio ${icon('plus')}</summary>${vendor.description.slice(2).map(text => `<p>${e(text)}</p>`).join('')}</details>` : ''}</div>${vendor.highlights.length ? `<div class="vp-highlights">${vendor.highlights.map(item => `<div>${icon(item.icon)}<div><h3>${e(item.title)}</h3><p>${e(item.text)}</p></div></div>`).join('')}</div>` : ''}${vendor.services.length ? `<div class="vp-services"><h3>How we can help</h3>${vendor.services.map(text => `<span>${icon('check')}${e(text)}</span>`).join('')}</div>` : ''}${vendor.styles.length ? `<div class="vp-styles"><div><p class="vp-eyebrow">THE FEELING</p><h3>A style that speaks to you.</h3></div><div>${vendor.styles.map(style => `<span class="vp-tag">${e(style)}</span>`).join('')}</div></div>` : ''}</section>
  <section class="vp-section" id="packages">${title('THE DETAILS, BEAUTIFULLY CLEAR', 'A starting point for your day.')}<p class="vp-section-intro">${e(vendor.pricing.note || 'Your proposal will confirm the full scope and price.')}</p><p class="vp-pricing-baseline">${e(priceLabel(vendor.pricing, vendor.pricing.currency))}<span>${e(vendor.pricing.currency)} · ${vendor.isFictional ? 'sample pricing' : 'starting price'}</span></p>${vendor.packages.length ? `<div class="vp-packages">${vendor.packages.map(pkg => renderPackage(pkg, vendor, pkg.id === recommended)).join('')}</div>` : `<div class="vp-empty"><h3>Made around your plans.</h3><p>This vendor creates individual proposals rather than publishing set packages. Share a little about your wedding to explore pricing.</p>${button('Request a custom quote ' + icon('arrow'), 'enquire', 'vp-button', 'data-type="quote"')}</div>`}${vendor.pricing.pricingGuideAvailable ? `<div class="vp-guide-note">${icon('message')}<div><strong>Like the whole picture?</strong><p>Ask for the pricing guide before planning the details.</p></div>${button('Request pricing guide ' + icon('arrow'), 'enquire', 'vp-text-button', 'data-type="guide"')}</div>` : ''}${vendor.pricing.publicGuideUrl ? `<a class="vp-text-button" href="${e(vendor.pricing.publicGuideUrl)}" download>Download public pricing guide ${icon('arrow')}</a>` : ''}<div class="vp-comparison-entry">${button(icon('compare') + ' Compare this vendor', 'compare', 'vp-outline-button')}</div></section>
  <section class="vp-section" id="availability">${title('A DATE TO LOOK FORWARD TO', 'Will your day be our day?')}<div data-availability>${renderAvailability(vendor, date, month)}</div></section>
  ${facts.length ? `<section class="vp-section" id="quick-facts">${title('GOOD TO KNOW', 'The practical little things.')}<dl class="vp-facts">${facts.map(fact => `<div><dt>${e(fact.label)}</dt><dd>${e(fact.value)}</dd></div>`).join('')}</dl></section>` : ''}
  ${vendor.portfolioGalleries.length || vendor.media.videos.length ? `<section class="vp-section" id="portfolio">${title('A LITTLE INSPIRATION', 'Days we would do all over again.')}<p class="vp-section-intro">Sample wedding stories, brought together to show how a portfolio will feel.</p><div class="vp-portfolio-grid">${vendor.portfolioGalleries.map(collection => button(`${image(collection.cover)}<span class="vp-portfolio-copy"><small>${e(collection.location)} · ${e(collection.year)}</small><strong>${e(collection.title)}</strong><span>Explore the wedding ${icon('arrow')}</span></span>`, 'portfolio', 'vp-portfolio-card', `data-collection="${e(collection.id)}"`)).join('')}</div>${vendor.media.videos.map((video, i) => `<div class="vp-film">${button(`<img src="${e(video.poster)}" alt="${e(video.title)}" loading="lazy" width="160" height="110"><span>${icon('play')}</span>`, 'video', 'vp-film-preview', `data-video="${i}" aria-label="Play ${e(video.title)}"`)}<div><p class="vp-eyebrow">IN MOTION</p><h3>${e(video.title)}</h3><p>${e(video.description)}</p></div></div>`).join('')}</section>` : ''}
  <section class="vp-section" id="location">${title('NEAR YOU, AND A LITTLE FURTHER', 'Where we make things happen.')}<p class="vp-section-intro">Based in ${e(vendor.location.displayLocation)}${vendor.location.travelsOutsideServiceArea ? ', with travel by arrangement.' : '.'}</p><div class="vp-tags">${vendor.location.serviceAreas.map(area => `<span class="vp-tag">${e(area)}</span>`).join('')}</div>${vendor.location.coordinates ? `<div class="vp-map" data-map><svg viewBox="0 0 800 330" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><rect width="800" height="330" fill="#e9ede4"/><path d="M540-20q-100 100-15 175T590 360H850V0" fill="#d2e4e3"/><g stroke="#fff" stroke-width="10" fill="none"><path d="M0 40 700 340M-20 160 540 60M0 290 610 165M100-10 300 350M350-20 430 350M0 220 550 300"/></g><g fill="#d8dfd0"><path d="m140 50 80 50-60 40-70-50Z"/><path d="m310 180 90 40-65 65-80-50Z"/><path d="m440 40 55 25-20 70-45-40Z"/></g></svg><span class="vp-map-pin">${icon('pin')}<strong>${e(vendor.location.displayLocation)}</strong></span>${button('Explore map ' + icon('arrow'), 'map', 'vp-gallery-control')}<span class="vp-map-attribution">Illustrative area map</span></div><p class="vp-fine">${e(vendor.location.showExactAddress ? vendor.location.publicAddress || vendor.location.mapLabel : 'Approximate operating area only. A private studio or residential address is not displayed.')}</p>` : ''}<div class="vp-travel-note">${icon('truck')}<div><h3>${vendor.location.travelsOutsideServiceArea ? 'A little further afield?' : 'Getting here'}</h3><p>${e(vendor.location.travelNote || 'Ask about location, access and travel requirements.')}</p>${vendor.location.travelFeesMayApply ? '<p class="vp-fine">Travel fees may apply. Confirm them in your written quote.</p>' : ''}</div></div></section>
  <section class="vp-section" id="reviews">${title('KIND WORDS, KEPT CLOSE', 'The people behind the celebrations.', stats.count ? `<div class="vp-review-total">${icon('star')}<strong>${stats.average.toFixed(1)}</strong><span>${stats.count} sample reviews</span></div>` : '')}${stats.count ? `<div class="vp-review-toolbar"><p>Fictional feedback for this profile demonstration.</p><label>Sort by <select data-review-sort aria-label="Sort reviews"><option value="recent">Most recent</option><option value="highest">Highest rating</option><option value="lowest">Lowest rating</option></select></label></div>` : ''}<div data-reviews>${renderReviews(vendor)}</div>${stats.count > 3 ? button('View all ' + stats.count + ' reviews ' + icon('plus'), 'more-reviews', 'vp-outline-button', 'data-more-reviews') : ''}</section>
  ${vendor.consultations.length ? `<section class="vp-consult-section" id="consultation"><p class="vp-eyebrow">START WITH A CONVERSATION</p><h2>A few ideas.<br>A little possibility.</h2>${vendor.consultations.map(option => `<article><h3>${e(option.name)}</h3><p>${e(option.description)}</p><p class="vp-fine">${e(option.duration)} · ${e(option.modes.join(' or '))}<br>${e(option.priceLabel)}</p>${button('Request a consultation ' + icon('arrow'), 'consultation', 'vp-button', `data-consultation="${e(option.id)}"`)}</article>`).join('')}</section>` : ''}
  ${vendor.faqs.length ? `<section class="vp-section vp-faqs" id="faqs">${title('A LITTLE CLARITY', 'You might be wondering.')}<div>${vendor.faqs.map(([q, a]) => `<details><summary>${e(q)}${icon('plus')}</summary><p>${e(a)}</p></details>`).join('')}</div></section>` : ''}
  </div><aside class="vp-sidebar"><div class="vp-enquiry-card"><p class="vp-eyebrow">YOUR DAY STARTS HERE</p><p class="vp-sidebar-price">${e(priceLabel(vendor.pricing, vendor.pricing.currency))}</p><p class="vp-sidebar-note">${e(vendor.pricing.currency)} · ${vendor.pricing.startingPriceType === 'minimum_spend' ? 'minimum wedding spend' : 'indicative starting price'}</p><div class="vp-sidebar-divider"></div><h2>Let’s bring it<br>to life.</h2><p>Share your plans, ask a question or explore what’s possible for your day.</p><label class="vp-field"><span>${icon('calendar')} Wedding date</span><input type="date" data-sidebar-date value="${e(date)}"></label>${button('Enquire now ' + icon('arrow'), 'enquire', 'vp-button', 'data-type="general"')}<p class="vp-fine vp-center">A conversation, with no commitment.</p><div class="vp-sidebar-links">${vendor.pricing.pricingGuideAvailable ? button('Request pricing guide', 'enquire', 'vp-text-button', 'data-type="guide"') : ''}${button(icon('compare') + ' Compare this vendor', 'compare', 'vp-text-button')}</div><div class="vp-prototype-note">${icon('info')}<span>Sample profile. Requests stay in this preview.</span></div></div><div class="vp-side-caption">Good people.<br><em>Your kind of wedding.</em></div></aside></div>
  <div class="vp-bottom-note">A fictional studio. A real feel for what comes next.<span>All business details, reviews and wedding stories on this preview are illustrative. Photography is from Unsplash; the short nature clip is a CC0 media example.</span></div></div>
  <div class="vp-mobile-bar"><div><small>${vendor.pricing.startingPriceType === 'minimum_spend' ? 'MINIMUM SPEND' : 'STARTING FROM'}</small><strong>${e(money(vendor.pricing.startingPrice, vendor.pricing.currency))}${vendor.pricing.startingPriceType === 'per_person' ? ' / guest' : vendor.pricing.startingPriceType === 'per_item' ? ' / item' : ''}</strong></div>${button('Enquire ' + icon('arrow'), 'enquire', 'vp-button', 'data-type="general"')}</div>`;
}
